                                  Map<String, String> query,
                                  Set<String> queryEnabledPaths,
                                  Map<String, String> credentialOwners) {
        if (path == null || headers == null || query == null
                || queryEnabledPaths == null || credentialOwners == null) {
            throw new IllegalArgumentException("Null input");
