import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class SolutionTest {
    public static void main(String[] args) {
        Map<String, String> headers = new HashMap<>();
        Map<String, String> query = new HashMap<>();
        Set<String> enabled = new HashSet<>();
        Map<String, String> owners = new HashMap<>();
        enabled.add("/allowed");
        owners.put("abc", "Alice");
        owners.put("query-key", "Quinn");
        owners.put("blank-owner", "   ");

        headers.put("Authorization", "Token   abc  ");
        query.put("access_token", "query-key");
        eq("Alice", Solution.identify("/allowed", headers, query, enabled, owners));

        headers.put("Authorization", "Token unknown");
        eq("", Solution.identify("/allowed", headers, query, enabled, owners));

        headers.put("Authorization", "Bearer abc");
        eq("Quinn", Solution.identify("/allowed", headers, query, enabled, owners));
        eq("", Solution.identify("/disabled", headers, query, enabled, owners));

        headers.put("Authorization", "Token    ");
        eq("Quinn", Solution.identify("/allowed", headers, query, enabled, owners));
        query.put("access_token", "  ");
        eq("", Solution.identify("/allowed", headers, query, enabled, owners));

        query.put("access_token", "blank-owner");
        eq("", Solution.identify("/allowed", headers, query, enabled, owners));
        headers.clear();
        query.put("access_token", "  query-key  ");
        eq("Quinn", Solution.identify("/allowed", headers, query, enabled, owners));

        Map<String, String> headersBefore = new HashMap<>(headers);
        Map<String, String> queryBefore = new HashMap<>(query);
        Set<String> enabledBefore = new HashSet<>(enabled);
        Map<String, String> ownersBefore = new HashMap<>(owners);
        Solution.identify("/allowed", headers, query, enabled, owners);
        eq(headersBefore, headers);
        eq(queryBefore, query);
        eq(enabledBefore, enabled);
        eq(ownersBefore, owners);

        Map<String, String> wrongCase = new HashMap<>();
        wrongCase.put("authorization", "Token abc");
        eq("", Solution.identify("/allowed", wrongCase, new HashMap<String, String>(), enabled, owners));

        bad(() -> Solution.identify(null, headers, query, enabled, owners));
        bad(() -> Solution.identify("/allowed", null, query, enabled, owners));
        bad(() -> Solution.identify("/allowed", headers, null, enabled, owners));
        bad(() -> Solution.identify("/allowed", headers, query, null, owners));
        bad(() -> Solution.identify("/allowed", headers, query, enabled, null));

        Map<String, String> nullKey = new HashMap<>();
        nullKey.put(null, "x");
        bad(() -> Solution.identify("/allowed", nullKey, query, enabled, owners));
        Map<String, String> nullValue = new HashMap<>();
        nullValue.put("x", null);
        bad(() -> Solution.identify("/allowed", headers, nullValue, enabled, owners));
        Set<String> nullPath = new HashSet<>();
        nullPath.add(null);
        bad(() -> Solution.identify("/allowed", headers, query, nullPath, owners));
        Map<String, String> badOwners = new HashMap<>();
        badOwners.put("x", null);
        bad(() -> Solution.identify("/allowed", headers, query, enabled, badOwners));
    }

    private static void eq(Object expected, Object actual) {
        if (!expected.equals(actual)) throw new AssertionError("Expected " + expected + " but got " + actual);
    }

    private static void bad(Runnable action) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }
}

